-- PostgreSQL, 19 bảng thiết kế LibMan. Chạy trên database mới dành riêng cho demo.
-- DDL tham chiếu; chưa được thực thi kiểm thử ở môi trường tạo file.
-- Tên quoted giữ chính xác cách viết trong ERD. Không DROP; nếu đã có bảng, dừng và kiểm tra.
BEGIN;
CREATE TABLE "tblStaff" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "staffCode" varchar(30) NOT NULL UNIQUE,
    "fullName" varchar(150) NOT NULL,
    "username" varchar(100) NOT NULL UNIQUE,
    "password" varchar(255) NOT NULL
);
CREATE TABLE "tblManagementStaff" (
    "tblStaffid" bigint PRIMARY KEY REFERENCES "tblStaff"("id")
);
CREATE TABLE "tblLibraryStaff" (
    "id" bigint PRIMARY KEY REFERENCES "tblStaff"("id")
);
CREATE TABLE "tblReader" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "cccd" char(12) NOT NULL UNIQUE,
    "fullName" varchar(150) NOT NULL,
    "dateOfBirth" date NOT NULL,
    "address" varchar(255) NOT NULL,
    "phone" varchar(20) NOT NULL,
    "email" varchar(254) NOT NULL
);
CREATE TABLE "tblReaderCard" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "cardCode" varchar(30) NOT NULL UNIQUE,
    "issueDate" date NOT NULL,
    "status" varchar(20) NOT NULL,
    "readerId" bigint NOT NULL UNIQUE REFERENCES "tblReader"("id")
);
CREATE TABLE "tblAuthor" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "authorName" varchar(150) NOT NULL
);
CREATE TABLE "tblPublisher" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "publisherName" varchar(150) NOT NULL
);
CREATE TABLE "tblCategory" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "categoryName" varchar(150) NOT NULL
);
CREATE TABLE "tblDocument" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "documentCode" varchar(30) NOT NULL UNIQUE,
    "title" varchar(255) NOT NULL,
    "publicationYear" integer NOT NULL,
    "edition" varchar(100),
    "tblPublisherid" bigint REFERENCES "tblPublisher"("id")
);
CREATE TABLE "tblDocumentCopy" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "copyCode" varchar(30) NOT NULL UNIQUE,
    "status" varchar(20) NOT NULL,
    "condition" varchar(30) NOT NULL,
    "tblDocumentid" bigint NOT NULL REFERENCES "tblDocument"("id")
);
CREATE TABLE "tblDocumentAuthor" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tblDocumentid" bigint NOT NULL REFERENCES "tblDocument"("id"),
    "tblAuthorid" bigint NOT NULL REFERENCES "tblAuthor"("id"),
    UNIQUE ("tblDocumentid", "tblAuthorid")
);
CREATE TABLE "tblDocumentCategory" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tblDocumentid" bigint NOT NULL REFERENCES "tblDocument"("id"),
    "tblCategoryid" bigint NOT NULL REFERENCES "tblCategory"("id"),
    UNIQUE ("tblDocumentid", "tblCategoryid")
);
CREATE TABLE "tblLoan" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "loanCode" varchar(30) NOT NULL UNIQUE,
    "loanDate" date NOT NULL,
    "dueDate" date NOT NULL,
    "tblReaderid" bigint NOT NULL REFERENCES "tblReader"("id")
);
CREATE TABLE "tblLoanDetail" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tblLoanid" bigint NOT NULL REFERENCES "tblLoan"("id"),
    "tblDocumentCopyid" bigint NOT NULL REFERENCES "tblDocumentCopy"("id"),
    UNIQUE ("tblLoanid", "tblDocumentCopyid")
);
CREATE TABLE "tblReturnReceipt" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "returnCode" varchar(30) NOT NULL UNIQUE,
    "returnDate" date NOT NULL,
    "tblReaderid" bigint NOT NULL REFERENCES "tblReader"("id"),
    "tblLibraryStaffid" bigint NOT NULL REFERENCES "tblLibraryStaff"("id")
);
CREATE TABLE "tblReturnDetail" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "lateFine" numeric(18,2) NOT NULL,
    "damageFine" numeric(18,2) NOT NULL,
    "tblReturnReceiptid" bigint NOT NULL REFERENCES "tblReturnReceipt"("id"),
    "tblLoanDetailid" bigint NOT NULL UNIQUE REFERENCES "tblLoanDetail"("id")
);
CREATE TABLE "tblSupplier" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "supplierName" varchar(200) NOT NULL,
    "taxCode" varchar(30) NOT NULL UNIQUE,
    "address" varchar(255) NOT NULL,
    "phone" varchar(20) NOT NULL,
    "email" varchar(254)
);
CREATE TABLE "tblImportInvoice" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "invoiceCode" varchar(30) NOT NULL UNIQUE,
    "importDate" date NOT NULL,
    "totalAmount" numeric(18,2) NOT NULL,
    "tblSupplierid" bigint NOT NULL REFERENCES "tblSupplier"("id"),
    "tblLibraryStaffid" bigint NOT NULL REFERENCES "tblLibraryStaff"("id")
);
CREATE TABLE "tblImportInvoiceDetail" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "quantity" integer NOT NULL,
    "unitPrice" numeric(18,2) NOT NULL,
    "tblImportInvoiceid" bigint NOT NULL REFERENCES "tblImportInvoice"("id"),
    "tblDocumentid" bigint NOT NULL REFERENCES "tblDocument"("id"),
    UNIQUE ("tblImportInvoiceid", "tblDocumentid")
);
COMMIT;
